/**
 * lod.ts — how much building you get at how far.
 *
 * Four tiers:
 *   0  full detail   bays, fire escapes, stoops, cornice brackets, roof props
 *   1  medium        massing + bays + parapets + the big roof silhouette items
 *   2  coarse        one prism, one crown, one roof cap — still the real shader
 *   3  impostor      instanced boxes generated by a cheap skyline sampler
 *
 * Switching is driven by screen-space error, not by a hard-coded metre count.
 * The question a LOD system should answer is "how many pixels is the detail I
 * am about to drop", and that depends on vertical FOV and framebuffer height,
 * which change with the quality slider, the window size and the wingsuit FOV
 * boost. Deriving the radii from projection means the city looks identical on
 * a 4K ultrawide and a laptop, and costs proportionally the same.
 *
 * Transitions are dithered rather than instant. A chunk that is changing tier
 * renders both meshes for `FADE_SECONDS`, one dissolving in and one out, using
 * interleaved-gradient-noise screen-door alpha in the facade shader. No sorting,
 * no transparency pass, and TAA resolves the dither into a clean cross-fade.
 *
 * Public API
 * ----------
 *   buildLodPlan(quality, fovY, screenHeight)   the ring table for this frame
 *   lodForDistance(plan, distance)
 *   FADE_SECONDS
 *   screenErrorDistance(featureMetres, targetPixels, fovY, screenHeight)
 */
import type { QualitySettings } from "../../config";

/** Seconds a chunk spends cross-fading between two tiers. */
export const FADE_SECONDS = 0.42;

export interface LodRing {
  /** Tier index 0..2 (3 = impostor, handled by impostors.ts). */
  lod: number;
  /** Chunk edge length for this ring, metres. */
  chunkSize: number;
  /** Outer radius of the ring, metres. */
  radius: number;
  /** Does this tier cast shadows? Only the near rings do. */
  castShadow: boolean;
}

export interface LodPlan {
  rings: LodRing[];
  /** Outer radius of the last geometric ring — impostors begin here. */
  nearRadius: number;
  /** Outer radius of the impostor field. */
  impostorRadius: number;
  /** Impostor tile edge length, metres. */
  impostorTile: number;
  /** Pixels per metre at one metre distance — the projection scale. */
  pxPerMetre: number;
}

/**
 * Distance at which a feature of `featureMetres` subtends `targetPixels`.
 *
 * This is the whole LOD policy in one line: pick the smallest detail a tier
 * carries, decide how few pixels it may occupy before it is not worth its
 * vertices, and this gives you the switch distance.
 */
export function screenErrorDistance(
  featureMetres: number,
  targetPixels: number,
  fovY: number,
  screenHeight: number,
): number {
  const k = screenHeight / (2 * Math.tan((fovY * Math.PI) / 360));
  return (featureMetres * k) / Math.max(targetPixels, 0.25);
}

/**
 * Build the ring table.
 *
 * The screen-space radii are clamped by the quality tier's own budget — a
 * 4K screen would otherwise ask for full-detail geometry two kilometres out,
 * which is correct optically and catastrophic for memory.
 */
export function buildLodPlan(
  q: QualitySettings,
  fovY: number,
  screenHeight: number,
): LodPlan {
  const pxPerMetre = screenHeight / (2 * Math.tan((fovY * Math.PI) / 360));

  // Smallest feature each tier is responsible for, and the pixel budget below
  // which it stops paying for itself.
  //   tier 0 drops fire escapes / brackets  ~0.25 m detail at 1.6 px
  //   tier 1 drops bays and parapets        ~0.9 m detail at 1.6 px
  //   tier 2 drops the building itself      ~4 m detail at 1.4 px
  const r0 = screenErrorDistance(0.25, 1.6, fovY, screenHeight);
  const r1 = screenErrorDistance(0.9, 1.6, fovY, screenHeight);
  const r2 = screenErrorDistance(4.0, 1.4, fovY, screenHeight);

  const near0 = Math.min(r0, q.detailRadius * 0.5);
  const near1 = Math.min(Math.max(r1, near0 * 1.6), q.detailRadius * 1.25);
  const near2 = Math.min(Math.max(r2, near1 * 1.7), q.detailRadius * 2.9);

  const rings: LodRing[] = [
    { lod: 0, chunkSize: 320, radius: near0, castShadow: true },
    { lod: 1, chunkSize: 320, radius: near1, castShadow: true },
    // Tier 2 uses 3x chunks: a coarse building is ~40 vertices, so the whole
    // point is to stop paying per-chunk overhead, not per-vertex.
    { lod: 2, chunkSize: 960, radius: near2, castShadow: false },
  ];

  return {
    rings,
    nearRadius: near2,
    impostorRadius: Math.max(q.impostorRadius, near2 * 1.1),
    impostorTile: 1500,
    pxPerMetre,
  };
}

/**
 * Which tier a chunk at `distance` belongs to. Returns 3 for the impostor
 * field and 4 for "outside the world, do not build".
 */
export function lodForDistance(plan: LodPlan, distance: number): number {
  for (const r of plan.rings) if (distance <= r.radius) return r.lod;
  if (distance <= plan.impostorRadius) return 3;
  return 4;
}

/**
 * Hysteresis band, metres. A chunk sitting exactly on a ring boundary would
 * otherwise re-generate every time the camera breathes; a tier only changes
 * once the camera has committed by this much.
 */
export const LOD_HYSTERESIS = 45;

/** Apply hysteresis to a tier change. */
export function stableLod(
  plan: LodPlan,
  distance: number,
  currentLod: number,
): number {
  const want = lodForDistance(plan, distance);
  if (want === currentLod) return currentLod;
  // Moving to a coarser tier: require the chunk to be well past the boundary.
  const boundary =
    want > currentLod
      ? radiusOf(plan, currentLod) + LOD_HYSTERESIS
      : radiusOf(plan, want) - LOD_HYSTERESIS;
  if (want > currentLod) return distance > boundary ? want : currentLod;
  return distance < boundary ? want : currentLod;
}

function radiusOf(plan: LodPlan, lod: number): number {
  for (const r of plan.rings) if (r.lod === lod) return r.radius;
  return plan.impostorRadius;
}

/** Chunk edge length for a tier. */
export function chunkSizeForLod(plan: LodPlan, lod: number): number {
  for (const r of plan.rings) if (r.lod === lod) return r.chunkSize;
  return plan.impostorTile;
}

/** Does a tier cast into the shadow cascades? */
export function castsShadow(plan: LodPlan, lod: number): boolean {
  for (const r of plan.rings) if (r.lod === lod) return r.castShadow;
  return false;
}
